			sb.WriteString("; ")
		}
		errStr := err.Error()
		// Remove trailing period if present to avoid double punctuation
		if len(errStr) > 0 && errStr[len(errStr)-1] == '.' {
			errStr = errStr[:len(errStr)-1]
		}
		sb.WriteString(errStr)
	}

